-- ============================================================
-- STEP 0: Wipe all existing patient & visit rows before real import.
-- Visits go first because patients.id is FK-referenced by visits.patient_id
-- with ON DELETE RESTRICT.
-- This is a hard reset. Do not re-run after the real data is in.
-- ============================================================
delete from visits;
delete from patients;

-- ============================================================
-- STEP 1: Import real patient rows
-- ============================================================
do $$
declare
  v_clinic uuid;
  v_before int;
  v_after int;
begin
  select id into v_clinic from clinics limit 1;
  if v_clinic is null then
    raise exception 'No clinic row. Apply 0005_seed_dev.sql first.';
  end if;
  select count(*) into v_before from patients;

  ;

  select count(*) into v_after from patients;
  raise notice 'Imported % patient rows (% -> %).', v_after - v_before, v_before, v_after;
end$$;

